#include <cmath>

bool approxEqual(double a, double b)
{
    return std::abs(a - b) < 1e-9;
}

unitTests:
TEST("0.1 + 0.2 is close to 0.3") { CHECK(approxEqual(0.1 + 0.2, 0.3)); }
TEST("identical numbers are equal") { CHECK(approxEqual(5.0, 5.0)); }
TEST("clearly different numbers are not") { CHECK(!approxEqual(1.0, 1.1)); }
TEST("order does not matter") { CHECK(approxEqual(0.3, 0.1 + 0.2)); CHECK(!approxEqual(2.0, 1.0)); }

